```typescript
type Listener<TArgs extends unknown[]> = (...args: TArgs) => unknown;

interface EventEmitter {
  on<TArgs extends unknown[]>(eventName: string, listener: Listener<TArgs>): void;
  once<TArgs extends unknown[]>(eventName: string, listener: Listener<TArgs>): void;
  off<TArgs extends unknown[]>(eventName: string, listener: Listener<TArgs>): void;
  emit<TArgs extends unknown[]>(eventName: string, ...args: TArgs): unknown[];
  clear<TArgs extends unknown[]>(eventName: string): void;
}

function createEventEmitter(): EventEmitter {
  const listenersMap = new Map<string, Listener<unknown[]>[]>();

  return {
    on<TArgs extends unknown[]>(eventName: string, listener: Listener<TArgs>): void {
      if (!listenersMap.has(eventName)) {
        listenersMap.set(eventName, []);
      }
      listenersMap.get(eventName)!.push(listener as Listener<unknown[]>);
    },

    once<TArgs extends unknown[]>(eventName: string, listener: Listener<TArgs>): void {
      const wrappedListener: Listener<TArgs> = (...args: TArgs) => {
        this.off(eventName, wrappedListener as Listener<unknown[]>);
        return listener(...args);
      };
      wrappedListener.__once__ = true;
      this.on(eventName, wrappedListener as Listener<unknown[]>);
    },

    off<TArgs extends unknown[]>(eventName: string, listener: Listener<TArgs>): void {
      if (!listenersMap.has(eventName)) {
        return;
      }

      const eventListeners = listenersMap.get(eventName)!;
      const index = eventListeners.indexOf(listener as Listener<unknown[]>);

      if (index !== -1) {
        eventListeners.splice(index, 1);
      }
    },

    emit<TArgs extends unknown[]>(eventName: string, ...args: TArgs): unknown[] {
      if (!listenersMap.has(eventName)) {
        return [];
      }

      const eventListeners = [...listenersMap.get(eventName)!];
      const results: unknown[] = [];

      for (const listener of eventListeners) {
        const result = listener(...args);
        results.push(result);
      }

      return results;
    },

    clear<TArgs extends unknown[]>(eventName: string): void {
      if (listenersMap.has(eventName)) {
        listenersMap.delete(eventName);
      }
    }
  };
}

export { createEventEmitter };
