export function createEventEmitter() {
    const events = new Map<
        string,
        Array<{ listener: (...args: any[]) => any, once: boolean }>
    >();

    function on(event: string, listener: (...args: any[]) => any) {
        const listeners = events.get(event) ?? [];
        listeners.push({ listener, once: false });
        events.set(event, listeners);
    }

    function once(event: string, listener: (...args: any[]) => any) {
        const listeners = events.get(event) ?? [];
        listeners.push({ listener, once: true });
        events.set(event, listeners);
    }

    function off(event: string, listener: (...args: any[]) => any) {
        const listeners = events.get(event);
        if (!listeners) return;
        for (let i = 0; i < listeners.length; i++) {
            if (listeners[i].listener === listener) {
                listeners.splice(i, 1);
                break;
            }
        }
        if (listeners.length === 0) {
            events.delete(event);
        }
    }

    function emit(event: string, ...args: any[]): any[] {
        const listeners = events.get(event);
        if (!listeners) return [];
        const results: any[] = [];
        for (let i = 0; i < listeners.length;) {
            const entry = listeners[i];
            const result = entry.listener(...args);
            results.push(result);
            if (entry.once) {
                listeners.splice(i, 1);
            } else {
                i++;
            }
        }
        if (listeners.length === 0) {
            events.delete(event);
        }
        return results;
    }

    return { on, once, off, emit };
}
