export function createTodoApp(): TodoApp {
  const todos = new Map<number, Todo>();
  let nextId = 1;

  return {
    addTodo: (text) => {
      const todo: Todo = { id: nextId++, text, completed: false };
      todos.set(todo.id, todo);
      return todo;
    },
    getTodo: (id) => {
      const t = todos.get(id);
      return t !== undefined ? t : undefined;
    },
    toggleTodo: (id) => {
      const t = todos.get(id);
      if (t) {
        t.completed = !t.completed;
      }
    },
    deleteTodo: (id) => {
      return todos.delete(id);
    },
    listTodos: () => Array.from(todos.values()),
    listCompleted: () => Array.from(todos.values()).filter((t) => t.completed),
    listPending: () => Array.from(todos.values()).filter((t) => !t.completed),
    clearCompleted: () => {
      for (const [id, todo] of todos) {
        if (todo.completed) {
