export function createTtlCache(): TtlCache {
    const DEFAULT_TTL_MS = 1000;
    const entries = new Map<string, { value: unknown; expiresAt: number }>();

    const set = (key: string, value: unknown, nowMs: number, ttlMs?: number): void => {
        const ttl = typeof ttlMs === "number" ? ttlMs : DEFAULT_TTL_MS;
        const expiresAt = nowMs + ttl;
        entries.set(key, { value, expiresAt });
    };

    const get = (key: string, nowMs: number): unknown => {
        const entry = entries.get(key);
        if (!entry) return undefined;
        if (nowMs >= entry.expiresAt) {
            entries.delete(key);
            return undefined;
        }
        return entry.value;
    };

    const has = (key: string, nowMs: number): boolean => {
        const entry = entries.get(key);
        if (!entry) return false;
        if (nowMs >= entry.expiresAt) {
            entries.delete(key);
            return false;
        }
        return true;
    };

    const deleteKey = (key: string): boolean => entries.delete(key);

    const size = (nowMs: number): number => {
        for (const [k, entry] of entries) {
            if (nowMs >= entry.expiresAt) {
                entries.delete(k);
            }
        }
        return entries.size;
    };

    const clear = (): void => {
        entries.clear();
    };

    return { set, get, has, delete: deleteKey, size, clear };
}
