function createTodoApp() {
  let nextId = 1;
  const todos: Array<{ id: number; text: string; completed: boolean }> = [];

  const addTodo = (text: string) => {
    const todo = { id: nextId++, text, completed: false };
    todos.push(todo);
    return todo;
  };

  const getTodo = (id: number) => todos.find(t => t.id === id);

  const toggleTodo = (id: number) => {
    const todo = getTodo(id);
    if (todo) {
      todo.completed = !todo.completed;
    }
  };

  const deleteTodo = (id: number): boolean => {
    const index = todos.findIndex(t => t.id === id);
    if (index === -1) return false;
    todos.splice(index, 1);
    return true;
  };

  const listTodos = (): Array<{ id: number; text: string; completed: boolean }> => todos;

  const listCompleted = (): Array<{ id: number; text: string; completed: boolean }> =>
    todos.filter(t => t.completed);

  const listPending = (): Array<{ id: number; text: string; completed: boolean }> =>
    todos.filter(t => !t.completed);

  const clearCompleted = (): void => {
    todos = todos.filter(t => !t.completed);
  };

  return {
    addTodo,
    getTodo,
    toggleTodo,
    deleteTodo,
    listTodos,
    listCompleted,
    listPending,
    clearCompleted,
  };
}

