        add: (n: number) => {
            current += n;
            return calculator;
        },
        subtract: (n: number) => {
            current -= n;
            return calculator;
        },
        multiply: (n: number) => {
            current *= n;
            return calculator;
        },
        divide: (n: number) => {
            current /= n;
            return calculator;
