interface RateLimiter {
  allow(key: string, nowMs: number): boolean
  remaining(key: string, nowMs: number): number
  reset(key: string): void
}

const LIMIT = 3
const WINDOW_MS = 1000

export function createRateLimiter(): RateLimiter {
  const keyStates = new Map<string, { usage: number; windowStart: number }>()

  const getOrCreateState = (key: string, nowMs: number): { usage: number; windowStart: number } => {
    const state = keyStates.get(key)
    if (state) {
      // Boundary reset rule
      if (nowMs - state.windowStart >= WINDOW_MS) {
        state.usage = 0
        state.windowStart = nowMs
      }
      return state
    }
    const newState = { usage: 0, windowStart: nowMs }
    keyStates.set(key, newState)
    return newState
  }

  return {
    allow(key: string, nowMs: number): boolean {
      const state = getOrCreateState(key, nowMs)
      if (state.usage < LIMIT) {
        state.usage++
        return true
      }
      return false
    },
    remaining(key: string, nowMs: number): number {
      const state = keyStates.get(key)
      if (!state) {
        // If key doesn't exist, treat as 0 usage in current/fresh window
        return LIMIT
      }

      // Check if window expired
      if (nowMs - state.windowStart >= WINDOW_MS) {
        return LIMIT
      }

      return Math.max(0, LIMIT - state.usage)
    },
    reset(key: string): void {
      keyStates.delete(key)
    },
  }
}
