export function createEventEmitter() {
  const events = new Map();
  function on(eventName, listener) {
    const listeners = events.get(eventName) || [];
    listeners.push({ handler: listener, once: false });
    events.set(eventName, listeners);
  }
  function once(eventName, listener) {
    const listeners = events.get(eventName) || [];
    listeners.push({ handler: listener, once: true });
    events.set(eventName, listeners);
  }
  function off(eventName, listener) {
    const listeners = events.get(eventName) || [];
    for (let i = 0; i < listeners.length; i++) {
      if (listeners[i].handler === listener) {
        listeners.splice(i, 1);
        events.set(eventName, listeners);
        return;
      }
    }
  }
  function emit(eventName, ...args) {
    const listeners = events.get(eventName) || [];
    const results = [];
    for (const listener of listeners) {
      results.push(listener.handler(...args));
    }
    const filteredListeners = listeners.filter(l => !l.once);
    events.set(eventName, filteredListeners);
    return results;
  }
  return { on, once, off, emit };
}
