  set(key: string, value: unknown, nowMs: number, ttlMs?: number): void {
    const expiresAt = nowMs + (ttlMs ?? 1000);
    this.map.set(key, { value, expiresAt });
  }
  get(key: string, nowMs: number): unknown {
    const entry = this.map.get(key);
    if (!entry) return undefined;
    if (nowMs >= entry.expiresAt) return undefined;
    return entry.value;
  }
  has(key: string, nowMs: number): boolean {
    const entry = this.map.get(key);
    return entry != null && nowMs < entry.expiresAt;
  }
  delete(key: string): boolean {
    return this.map.delete(key);
  }
  size(nowMs: number): number {
    let count = 0;
    for (const entry of this.map.values()) {
      if (nowMs < entry.expiresAt) count++;
    }
    return count;
  }
  clear(): void {
    this.map.clear();
  }
}

export function createTtlCache(): TtlCache {
  return new TtlCacheImpl();
}
