export function createEventEmitter() {
  const events = new Map<string, Array<{ once: boolean; callback: (...args: any[]) => any }>>();

  return {
    on(eventName: string, callback: (...args: any[]) => any) {
      if (!events.has(eventName)) {
        events.set(eventName, []);
      }
      events.get(eventName)!.push({ once: false, callback });
    },

    once(eventName: string, callback: (...args: any[]) => any) {
      if (!events.has(eventName)) {
        events.set(eventName, []);
      }
      events.get(eventName)!.push({ once: true, callback });
    },

    off(eventName: string, callback: (...args: any[]) => any) {
      if (events.has(eventName)) {
        events.set(
          eventName,
          events.get(eventName)!.filter(({ callback: cb }) => cb !== callback)
        );
      }
    },

    emit(eventName: string, ...args: any[]) {
      if (!events.has(eventName)) return [];
      const listeners = [...events.get(eventName)!];
      const results: any[] = [];
      for (let i = 0; i < listeners.length; i++) {
        const { once, callback } = listeners[i];
        results.push(callback(...args));
        if (once) {
          events.get(eventName)!.splice(i, 1);
          i--;
        }
      }
      return results;
    },
  };
}
