export function createEventEmitter(): EventEmitter {
  const listeners = new Map<string, Listener[]>();

  return {
    on(event: string, listener: Listener): number {
      if (!listeners.has(event)) {
        listeners.set(event, []);
      }
      listeners.get(event)!.push(listener);
      return this.listenerCount(event);
    },

    once(event: string, listener: Listener): number {
      const wrapper = (...args: unknown[]) => {
        listener(...args);
        this.off(event, wrapper);
      };
      return this.on(event, wrapper);
    },

    off(event: string, listener: Listener): boolean {
      if (!listeners.has(event)) return false;
      const index = listeners.get(event)!.findIndex(l => l === listener);
      if (index === -1) return false;
      listeners.get(event)!.splice(index, 1);
      return true;
    },

    emit(event: string, payload: unknown): unknown[] {
      if (!listeners.has(event)) return [];
      const results = listeners.get(event)!.map(listener => listener(payload));
      return results;
    },

    listenerCount(event: string): number {
      return listeners.get(event)?.length ?? 0;
    }
  };
}

type Listener = (payload: unknown) => unknown;

interface EventEmitter {
  on(event: string, listener: Listener): number;
  once(event: string, listener: Listener): number;
  off(event: string, listener: Listener): boolean;
  emit(event: string, payload: unknown): unknown[];
  listenerCount(event: string): number;
}
