export function createRateLimiter(nowMs: () => number): { allow(key: string): boolean; reset(key: string): void } {
    const quotas = new Map<string, { windowStart: number; allowedCount: number }>();

    return {
        allow(key: string) {
            const now = nowMs();
            let entry = quotas.get(key);

            if (!entry || now - entry.windowStart > 1000) {
                entry = { windowStart: now, allowedCount: 0 };
                quotas.set(key, entry);
            }

            if (entry.allowedCount < 3) {
                entry.allowedCount++;
                return true;
            }

            return false;
        },
        reset(key: string) {
            quotas.delete(key);
        }
    };
}
