        if (emitter.listeners[event]) {
            const index = emitter.listeners[event].indexOf(listener);
            if (index !== -1) {
                emitter.listeners[event].splice(index, 1);
                return true;
            }
        }
        return false;
    };

    const removeOnceListener = (event: string, listener: Listener) => {
        if (emitter.onceListeners[event]) {
            const index = emitter.onceListeners[event].indexOf(listener);
            if (index !== -1) {
                emitter.onceListeners[event].splice(index, 1);
                return true;
            }
        }
        return false;
    };

    const emit = (event: string, payload: unknown) => {
        const listeners = emitter.listeners[event] || [];
        const onceListeners = emitter.onceListeners[event] || [];
        const result: unknown[] = [];

        for (const listener of listeners) {
            const returnValue = listener(payload);
            result.push(returnValue);
        }

        for (const listener of onceListeners) {
            const returnValue = listener(payload);
            result.push(returnValue);
            removeOnceListener(event, listener);
        }

        return result;
    };

    const listenerCount = (event: string) => {
        return (emitter.listeners[event] || []).length;
    };

    return {
        on(event: string, listener: Listener): number {
            addListener(event, listener);
            return listenerCount(event);
        },
        once(event: string, listener: Listener): number {
            addOnceListener(event, listener);
            return listenerCount(event);
        },
        off(event: string, listener: Listener): boolean {
            return removeListener(event, listener) || removeOnceListener(event, listener);
        },
        emit(event: string, payload: unknown): unknown[] {
            return emit(event, payload);
        },
        listenerCount(event: string): number {
            return listenerCount(event);
        }
    };
}
