        rateLimit: {
            requests: 3,
            windowMs: 1000,
        },
        track: (key: string, nowMs: number) => {
            const entry = this.state[key];
            if (!entry) {
                entry = { lastRequestMs: nowMs, count: 0 };
                this.state[key] = entry;
            }
            const elapsed = nowMs - entry.lastRequestMs;
            if (elapsed >= this.rateLimit.windowMs) {
                entry.count = 0;
                entry.lastRequestMs = nowMs;
            }
            entry.count++;
            return entry.count <= this.rateLimit.requests;
        },
        reset: (key: string) => {
            delete this.state[key];
        },
    };

    this.state = {};
    return rateLimiter;
