interface EventEmitter {
  on<T>(eventName: string, listener: (event: T) => any): void;
  once<T>(eventName: string, listener: (event: T) => any): void;
  off<T>(eventName: string, listener: (event: T) => any): void;
  emit<T>(eventName: string, ...args: any[]): any[];
}

const eventMap: { [key: string]: ((event: any) => any)[] } = {};

function createEventEmitter(): EventEmitter {
  return {
    on: (eventName: string, listener: (event: any) => any) => {
      if (!eventMap[eventName]) {
        eventMap[eventName] = [];
      }
      eventMap[eventName].push(listener);
    },
    once: (eventName: string, listener: (event: any) => any) => {
      const wrappedListener = (...args: any[]) => {
        listener(...args);
        this.off(eventName, wrappedListener);
      };
      this.on(eventName, wrappedListener);
    },
    off: (eventName: string, listener: (event: any) => any) => {
      if (eventMap[eventName]) {
        const index = eventMap[eventName].indexOf(listener);
        if (index !== -1) {
          eventMap[eventName].splice(index, 1);
        }
      }
    },
    emit: (eventName: string, ...args: any[]) => {
      if (eventMap[eventName]) {
        return eventMap[eventName].map((listener) => listener(...args));
      } else {
        throw new Error(`Event '${eventName}' does not exist`);
      }
    },
  };
}
