export class EventEmitter {
  private listeners: { [key: string]: Listener[] } = {};
  private listenerCount: { [key: string]: number } = {};

  createListener(event: string, listener: Listener): number {
    if (!this.listeners[event]) {
      this.listeners[event] = [];
      this.listenerCount[event] = 0;
    }

    const count = this.listenerCount[event];
    this.listenerCount[event]++;
    return count;

    // no need to call callback here
  }

  on(event: string, listener: Listener): number {
    return this.createListener(event, listener);
  }

  once(event: string, listener: Listener): number {
    const listenerId = this.createListener(event, listener);

    function wrapper(...args) {
      if (wrapper.invoked === undefined) {
        listener(...args);
        wrapper.invoked = true;
      }
    }

    return wrapper;
  }

  off(event: string, listener: Listener): boolean {
    const count = this.listenerCount[event];
    if (!count) {
      return false;
    }

    const index = this.listeners[event].indexOf(listener);

    if (index === -1) {
      return false;
    }

    this.listenerCount[event]--;
    delete this.listeners[event][index];

    return true;
  }

  emit(event: string, payload: unknown): unknown[] {
    const listeners = this.listeners[event];
    if (!listeners) {
      return [];
    }

    const result = new Array(listeners.length);
    for (let i = 0; i < listeners.length; i++) {
      result[i] = listeners[i](payload);
    }
    return result;
  }

  listenerCount(event: string): number | undefined {
    return this.listenerCount[event];
  }
}
