export type RateLimitingPolicy = {
  limit: number;
  periodMs: number;
};

interface RateLimiter {
  nowMs(key: string): number;
  quota(key: string, nowMs?: number): number | null;
  reset(key: string);
}

type RequestCount = number;

const policy: RateLimitingPolicy = {
  limit: 3,
  periodMs: 1000,
};

function createRateLimiter(): { [key: string]: any } {
  const rateLimiters: { [key: string]: any } = {};

  return function (key: string) {
    if (!(key in rateLimiters)) {
      rateLimiters[key] = {
        lastRequestMs: 0,
        requests: 0,
        nextWindowStartMs: 0,
      };
    }

    const nowMs = rateLimiters[key].nowMs;
    const quota = policy.limit;

    if (quota === 0) {
      delete rateLimiters[key];
      return null;
    }

    const timeSinceLastRequest = nowMs - rateLimiters[key].lastRequestMs;

    if (timeSinceLastRequest >= policy.periodMs) {
      rateLimiters[key].requests = 1;
      rateLimiters[key].nextWindowStartMs = nowMs + policy.periodMs;
      rateLimiters[key].lastRequestMs = nowMs;
    } else {
      const requestsInCurrentWindow =
        timeSinceLastRequest * quota / policy.periodMs;

      if (rateLimiters[key].requests! < requestsInCurrentWindow) {
        rateLimiters[key].requests += 1;
      }
    }

    return rateLimiters[key].requests;
  };

  function reset(key: string) {
    rateLimiters[key] = {
      lastRequestMs: 0,
      requests: 0,
      nextWindowStartMs: 0,
    };
  }

  Object.keys(rateLimiters).forEach((k) => rateLimiters[k] = null);

  return { reset, quota };
}
