export function createRateLimiter(): RateLimiter {
  const limit = 3;
  const windowMs = 1000;
  const keyToState: { [key: string]: { allowCount: number; windowStart: number } } = {};

  return (function rateLimiterFunction(key: string, nowMs: number) {
    if (!(key in keyToState)) {
      keyToState[key] = {
        allowCount: 0,
        windowStart: nowMs - limit * windowMs
      };
    }

    const { allowCount, windowStart } = keyToState[key];

    const isWithinWindow = nowMs - windowStart < windowMs;
    let remaining;

    if (isWithinWindow && allowCount > 0) {
      remaining = Math.max(0, limit - allowCount);
    } else {
      remaining = Infinity;
    }

    return isWithinWindow
      ? { allow: true, remaining }
      : { allow: false, remaining };
  })();
}
