export type TtlCache = {
  set(key: string, value: unknown, nowMs: number, ttlMs?: number): void;
  get(key: string, nowMs: number): unknown;
  has(key: string, nowMs: number): boolean;
  delete(key: string): boolean;
  size(nowMs: number): number;
  clear(): void;
};

export function createTtlCache(): TtlCache {
  const cache: { [key: string]: { value: unknown; expiresAt: number } } = {};

  function set(key: string, value: unknown, nowMs: number, ttlMs?: number) {
    if (ttlMs === undefined) {
      ttlMs = 1000;
    }

    cache[key] = {
      value,
      expiresAt: nowMs + ttlMs,
    };
  }

  function get(key: string, nowMs: number): unknown {
    const entry = cache[key];
    return entry ? entry.value : null;
  }

  function has(key: string, nowMs: number): boolean {
    const entry = cache[key];
    return entry !== undefined;
  }

  function delete_(key: string) {
    if (cache[key]) {
      delete cache[key];
      return true;
    }
    return false;
  }

  function size(nowMs: number): number {
    let count = 0;
    for (const key in cache) {
      const entry = cache[key];
      if (entry.expiresAt <= nowMs) break;
      ++count;
    }
    return count;
  }

  function clear() {
    cache = {};
  }

  return { set, get, has, delete: delete_, size, clear };
}
