type Listener<T extends unknown[]> = (...args: T) => unknown;

interface EventEmitter {
  on<E extends string>(event: E, listener: Listener<unknown[]>): () => void;
  once<E extends string>(event: E, listener: Listener<unknown[]>): () => void;
  off<E extends string>(event: E, listener: Listener<unknown[]>): void;
  emit<E extends string>(event: E, ...args: unknown[]): unknown[];
}

function createEventEmitter(): EventEmitter {
  const events: Record<string, Listener<unknown[]>[]> = {};

  function on<E extends string>(event: E, listener: Listener<unknown[]>): () => void {
    if (!events[event]) {
      events[event] = [];
    }
    events[event].push(listener);
    return () => {
      off(event, listener);
    };
  }

  function once<E extends string>(event: E, listener: Listener<unknown[]>): () => void {
    const wrapper: Listener<unknown[]> = (...args) => {
      off(event, wrapper);
      return listener(...args);
    };
    return on(event, wrapper);
  }

  function off<E extends string>(event: E, listener: Listener<unknown[]>): void {
    if (events[event]) {
      const index = events[event].indexOf(listener);
      if (index !== -1) {
        events[event].splice(index, 1);
      }
    }
  }

  function emit<E extends string>(event: E, ...args: unknown[]): unknown[] {
    const listeners = events[event];
    if (!listeners) {
      return [];
    }
    const results: unknown[] = [];
    for (const listener of listeners) {
      const result = listener(...args);
      results.push(result);
    }
    return results;
  }

  return {
    on,
    once,
    off,
    emit
  };
}

export { createEventEmitter };
export type { EventEmitter, Listener };
