function createEventEmitter(): EventEmitter {
  const events: Record<string, { listener: Listener; once: boolean }[]> = {}

  return {
    on(event: string, listener: Listener): number {
      if (!events[event]) {
        events[event] = []
      }
      events[event].push({ listener, once: false })
      return events[event].length
    },

    once(event: string, listener: Listener): number {
      if (!events[event]) {
        events[event] = []
      }
      events[event].push({ listener, once: true })
      return events[event].length
    },

    off(event: string, listener: Listener): boolean {
      if (!events[event]) {
        return false
      }
      const index = events[event].findIndex(
        (entry) => entry.listener === listener
      )
      if (index === -1) {
        return false
      }
      events[event].splice(index, 1)
      return true
    },

    emit(event: string, payload: unknown): unknown[] {
      if (!events[event]) {
        return []
      }
      const results: unknown[] = []
      const listeners = [...events[event]]
      for (const entry of listeners) {
        const result = entry.listener(payload)
        results.push(result)
        if (entry.once) {
          this.off(event, entry.listener)
        }
      }
      return results
    },

    listenerCount(event: string): number {
      return events[event] ? events[event].length : 0
    },
  }
}

export { createEventEmitter, type Listener }
