            const list = getListeners(event);
            list.push({ fn: listener, once: true });
            return this;
        },
        off(event, listener) {
            const list = listeners.get(event);
            if (!list) return;
            for (let i = 0; i < list.length; i++) {
                if (list[i].fn === listener) {
                    list.splice(i, 1);
                    break;
                }
            }
        },
        emit(event, ...args) {
            const list = listeners.get(event);
            if (!list) return [];
            const results = [];
            for (const entry of [...list]) {
                try {
                    results.push(entry.fn(...args));
                } catch (_) {}
                if (entry.once) {
                    const idx = list.indexOf(entry);
                    if (idx !== -1) {
                        list.splice(idx, 1);
                    }
                }
            }
            return results;
        }
    };
