    const toggleTodo = (id: number) => {
        const todo = todos.get(id);
        if (todo) {
            todo.completed = !todo.completed;
        }
    };

    const deleteTodo = (id: number): boolean => {
        return todos.delete(id);
    };

    const listTodos = (): Todo[] => Array.from(todos.values());

    const listCompleted = (): Todo[] => {
        const result: Todo[] = [];
        for (const todo of todos.values()) {
            if (todo.completed) {
                result.push(todo);
            }
        }
        return result;
    };

    const listPending = (): Todo[] => {
        const result: Todo[] = [];
        for (const todo of todos.values()) {
            if (!todo.completed) {
                result.push(todo);
            }
        }
        return result;
    };

    const clearCompleted = () => {
        for (const id of todos.keys()) {
            const todo = todos.get(id);
            if (todo && todo.completed) {
                todos.delete(id);
            }
        }
    };

    return {
        addTodo,
        getTodo,
        toggleTodo,
        deleteTodo,
        listTodos,
        listCompleted,
        listPending,
        clearCompleted,
    };
}

