export function createTtlCache() {
  const store = new Map<string, { value: unknown, expiresAt: number }>();
  return {
    set(key: string, value: unknown, nowMs: number, ttlMs?: number): void {
      const ttl = ttlMs ?? 1000;
      const expiresAt = nowMs + ttl;
      store.set(key, { value, expiresAt });
    },
    get(key: string, nowMs: number): unknown {
      const entry = store.get(key);
      if (!entry) return undefined;
      if (nowMs >= entry.expiresAt) {
        store.delete(key);
        return undefined;
      }
      return entry.value;
    },
    has(key: string, nowMs: number): boolean {
      const entry = store.get(key);
      if (!entry) return false;
      if (nowMs >= entry.expiresAt) {
        store.delete(key);
        return false;
      }
      return true;
    },
    delete(key: string): boolean {
      return store.delete(key);
    },
    size(nowMs: number): number {
      let count = 0;
      for (const [k, entry] of store.entries()) {
        if (nowMs < entry.expiresAt) {
          count++;
        } else {
          store.delete(k);
        }
      }
      return count;
    },
    clear(): void {
      store.clear();
    }
  };
}

export function createTtlCache(): TtlCache {
  const DEFAULT_TTL = 1000;
  type Entry = { value: unknown; expiresAt: number };
  const store = new Map<string, Entry>();
  return {
    set(key: string, value: unknown, nowMs: number, ttlMs?: number): void {
      const ttl = typeof ttlMs === 'number' ? ttlMs : DEFAULT_TTL;
      const expiresAt = ttl > 0 ? nowMs + ttl : nowMs;
      store.set(key, { value, expiresAt });
    },
    get(key: string, nowMs: number): unknown {
      const entry = store.get(key);
      if (!entry) return undefined;
      if (nowMs >= entry.expiresAt) {
        store.delete(key);
        return undefined;
      }
      return entry.value;
    },
    has(key: string, nowMs: number): boolean {
      const entry = store.get(key);
      if (!entry) return false;
      if (nowMs >= entry.expiresAt) {
        store.delete(key);
        return false;
      }
      return true;
    },
    delete(key: string): boolean {
      return store.delete(key);
    },
    size(nowMs: number): number {
      for (const [k, e] of store) {
        if (nowMs >= e.expiresAt) {
          store.delete(k);
        }
      }
