export type Listener = (payload: unknown) => unknown;

export interface EventEmitter {
  on(event: string, listener: Listener): number;
  once(event: string, listener: Listener): number;
  off(event: string, listener: Listener): boolean;
  emit(event: string, payload: unknown): unknown[];
  listenerCount(event: string): number;
}

class EventEmitter implements EventEmitter {
  private listeners: Map<string, Listener[]> = new Map();
  private onceListeners: Map<string, Listener[]> = new Map();

  on(event: string, listener: Listener): number {
    const arr = this.listeners.get(event) ?? [];
    arr.push(listener);
    this.listeners.set(event, arr);
    return arr.length;
  }

  once(event: string, listener: Listener): number {
    const arr = this.onceListeners.get(event) ?? [];
    arr.push(listener);
    this.onceListeners.set(event, arr);
    return arr.length;
  }

  off(event: string, listener: Listener): boolean {
    const arr = this.listeners.get(event);
    if (!arr) return false;
    const idx = arr.indexOf(listener);
    if (idx === -1) return false;
    arr.splice(idx, 1);
    return true;
  }

  emit(event: string, payload: unknown): unknown[] {
    const normal = this.listeners.get(event) ?? [];
    const once = this.onceListeners.get(event) ?? [];

    const results: unknown[] = [];

    for (const listener of normal) {
      results.push(listener(payload));
    }
    for (const listener of once) {
      results.push(listener(payload));
    }
    this.onceListeners.delete(event);
    return results;
  }

  listenerCount(event: string): number {
    return (this.listeners.get(event) || []).length;
  }
}

export function createEventEmitter(): EventEmitter {
  return new EventEmitter();
}
