export function createRateLimiter() {
  const states = new Map<string, { currentWindow: number; count: number }>();
  function allow(key: string, nowMs: number): boolean {
    const winStart = Math.floor(nowMs / 1000) * 1000;
    const state = states.get(key) ?? { currentWindow: winStart, count: 0 };
    if (state.currentWindow !== winStart) {
      state.currentWindow = winStart;
      state.count = 0;
    }
    if (state.count < 3) {
      state.count++;
      states.set(key, state);
      return true;
    }
    return false;
  }
  function reset(key: string): void {
    states.delete(key);
  }
  return { allow, reset };
}
