export function createRateLimiter() {
  const store = new Map<string, { lastReset: number, count: number }>();
  const windowSize = 1000;
  const limit = 3;

  return {
    check(key: string, nowMs: number): boolean {
      const state = store.get(key);

      if (!state) {
        store.set(key, { lastReset: nowMs, count: 1 });
        return true;
      }

      if (nowMs - state.lastReset >= windowSize) {
        store.set(key, { lastReset: nowMs, count: 1 });
        return true;
      }

      if (state.count >= limit) {
        return false;
      }

      store.set(key, { 
        lastReset: state.lastReset, 
        count: state.count + 1 
      });
      return true;
    },

    reset(key: string): void {
      store.delete(key);
    }
  };
}
