interface StoredKey {
  count: number
  windowStart: number
}

const defaultLimit = 3
const defaultWindowMs = 1000

function createRateLimiter(): RateLimiter {
  const storage = new Map<string, StoredKey>()

  function clearExpiredKeys(key: string, nowMs: number): void {
    const entry = storage.get(key)
    if (!entry) return

    if (nowMs - entry.windowStart >= defaultWindowMs) {
      storage.delete(key)
    }
  }

  function allow(key: string, nowMs: number): boolean {
    clearExpiredKeys(key, nowMs)

    const entry = storage.get(key)
    if (!entry) {
      storage.set(key, { count: 1, windowStart: nowMs })
      return true
    }

    if (entry.count < defaultLimit) {
      entry.count = (entry.count as number) + 1
      storage.set(key, entry)
      return true
    }

    return false
  }

  function remaining(key: string, nowMs: number): number {
    clearExpiredKeys(key, nowMs)

    const entry = storage.get(key)
    if (!entry) {
      return defaultLimit
    }

    return Math.max(defaultLimit - (entry.count as number), 0)
  }

  function reset(key: string): void {
    storage.delete(key)
  }

  return { allow, remaining, reset }
}

export { createRateLimiter, RateLimiter }
