```typescript
type Listener = (payload: unknown) => unknown;

interface EventEmitter {
  on<K extends string>(event: K, listener: Listener): number;
  once<K extends string>(event: K, listener: Listener): number;
  off<K extends string>(event: K, listener: Listener): boolean;
  emit<K extends string>(event: K, payload: unknown): unknown[];
  listenerCount<K extends string>(event: K): number;
}

export function createEventEmitter(): EventEmitter {
  const listeners: Map<string, Listener[]> = new Map();
  const onceListeners: Map<string, Listener[]> = new Map();

  return {
    on<K extends string>(event: K, listener: Listener): number {
      const eventListeners = listeners.get(event) || [];
      eventListeners.push(listener);
      listeners.set(event, eventListeners);
      return eventListeners.length;
    },

    once<K extends string>(event: K, listener: Listener): number {
      const eventOnceListeners = onceListeners.get(event) || [];
      eventOnceListeners.push(listener);
      onceListeners.set(event, eventOnceListeners);
      return eventOnceListeners.length;
    },

    off<K extends string>(event: K, listener: Listener): boolean {
      const eventListeners = listeners.get(event) || [];
      const index = eventListeners.indexOf(listener);

      if (index !== -1) {
        eventListeners.splice(index, 1);
        listeners.set(event, eventListeners);
        return true;
      }

      const eventOnceListeners = onceListeners.get(event) || [];
      const onceIndex = eventOnceListeners.indexOf(listener);

      if (onceIndex !== -1) {
        eventOnceListeners.splice(onceIndex, 1);
        onceListeners.set(event, eventOnceListeners);
        return true;
      }

      return false;
    },

    emit<K extends string>(event: K, payload: unknown): unknown[] {
      const results: unknown[] = [];
      const eventListeners = listeners.get(event) || [];
      const eventOnceListeners = onceListeners.get(event) || [];

      for (const listener of eventListeners) {
        results.push(listener(payload));
      }

      for (const listener of eventOnceListeners) {
        results.push(listener(payload));
      }

      onceListeners.set(event, []);

      return results;
    },

    listenerCount<K extends string>(event: K): number {
      return (listeners.get(event) || []).length + (onceListeners.get(event) || []).length;
    }
  };
}
