interface KeyLimiter {
    reset(): void;
}

interface RateLimiter {
    limit(key: string): boolean;
    reset(key: string): void;
}

function createRateLimiter(nowMs: () => number): RateLimiter {
    type State = {
        count: number;
        lastReset: number;
    };

    const keyStates: Map<string, State> = new Map();

    return {
        limit(key: string): boolean {
            const now = nowMs();
            const state = keyStates.get(key) || { count: 0, lastReset: now };
            const elapsed = now - state.lastReset;
            const allowed = elapsed >= 1000 || state.count < 3;

            if (allowed) {
                if (elapsed >= 1000) {
                    // Full window reset
                    keyStates.set(key, { count: 1, lastReset: now });
                } else if (state.count < 2) {
                    // Increment count but stay within window
                    keyStates.set(key, { count: state.count + 1, lastReset: state.lastReset });
                }
            }
            return allowed;
        },
        reset(key: string): void {
            keyStates.set(key, { count: 0, lastReset: nowMs() });
        },
    };
}
