export function createRateLimiter(): RateLimiter {
    const state: Record<string, { count: number; windowStart: number }> = {};

    return {
        allow(key, nowMs) {
            const entry = state[key] || {};
            if (nowMs - entry.windowStart >= 1000) {
                state[key] = { count: 1, windowStart: nowMs };
                return true;
            } else if (entry.count < 3) {
                state[key] = { ...entry, count: entry.count + 1 };
                return true;
            } else {
                return false;
            }
        },
        remaining(key, nowMs) {
            const entry = state[key] || {};
            if (nowMs - entry.windowStart >= 1000) {
                return 3;
            } else {
                return Math.max(0, 3 - entry.count);
            }
        },
        reset(key) {
            delete state[key];
        }
    };
}

interface RateLimiter {
    allow(key: string, nowMs: number): boolean;
    remaining(key: string, nowMs: number): number;
    reset(key: string): void;
}
