export interface TtlCache {
    set(key: string, value: unknown, nowMs: number, ttlMs?: number): void;
    get(key: string, nowMs: number): unknown;
    has(key: string, nowMs: number): boolean;
    delete(key: string): boolean;
    size(nowMs: number): number;
    clear(): void;
}

export function createTtlCache(): TtlCache {
    interface Entry {
        value: unknown;
        expiresAt: number;
    }

    const cache: Record<string, Entry> = {};

    return {
        set(key: string, value: unknown, nowMs: number, ttlMs = 1000): void {
            const expiresAt = ttlMs === 0 ? nowMs : nowMs + ttlMs;
            cache[key] = {
                value,
                expiresAt,
            };
        },
        get(key: string, nowMs: number): unknown {
            const entry = cache[key];
            return entry && entry.expiresAt >= nowMs ? entry.value : undefined;
        },
        has(key: string, nowMs: number): boolean {
            const entry = cache[key];
            return entry && nowMs < entry.expiresAt && entry !== undefined;
        },
        delete(key: string): boolean {
            if (cache[key]) {
                delete cache[key];
                return true;
            }
            return false;
        },
        size(nowMs: number): number {
            return Object.keys(cache).filter(key => nowMs < cache[key].expiresAt).length;
        },
        clear(): void {
            Object.keys(cache).forEach(key => delete cache[key]);
        },
    };
}
