export function createEventEmitter() {
  type Listener = (...args: any[]) => any;
  const events = new Map<string, Array<{ once: boolean, listener: Listener }>>();

  return {
    on(event: string, listener: Listener) {
      if (!events.has(event)) events.set(event, []);
      events.get(event)!.push({ once: false, listener });
    },

    once(event: string, listener: Listener) {
      if (!events.has(event)) events.set(event, []);
      events.get(event)!.push({ once: true, listener });
    },

    off(event: string, listener: Listener) {
      if (!events.has(event)) return;
      const idx = events.get(event)!.findIndex(p => p.listener === listener);
      if (idx !== -1) events.get(event)!.splice(idx, 1);
    },

    emit(event: string, ...args: any[]) {
      if (!events.has(event)) return [];
      const entries = [...events.get(event)!];
      events.set(event, entries.filter(f => !f.once));
      return entries.map(f => f.listener(...args));
    },


  };
}
