export type RateLimiter = {
  tryAcquire: (key: string, nowMs: number) => boolean;
  reset: (key: string) => void;
};

export const createRateLimiter = (): RateLimiter => {
  const windows = new Map<string, [number, number]>(); // [lastRequestTime, requestCount]

  return {
    tryAcquire: (key: string, nowMs: number): boolean => {
      const WINDOW_MS = 1000;
      const MAX_REQUESTS = 3;

      const [lastRequestTime, requestCount] = windows.get(key) || [0, 0];

      // Reset window if it has elapsed
      if (lastRequestTime + WINDOW_MS <= nowMs) {
        windows.set(key, [nowMs, 1]);
        return true;
      }

      // Check if adding another request would exceed the limit
      if (requestCount >= MAX_REQUESTS) {
        return false;
      }

      // Allow the request
      windows.set(key, [lastRequestTime, requestCount + 1]);
      return true;
    },

    reset: (key: string): void => {
      windows.delete(key);
    },
  };
};
