export function createTtlCache(): TtlCache {
  const entries = new Map<string, Record<string, unknown>>();

  function set(key: string, value: unknown, nowMs: number, ttlMs: number = 1000) {
    entries.set(key, {
      value,
      expiresAt: ttlMs === 0 ? nowMs : nowMs + ttlMs,
    });
  }

  function get(key: string, nowMs: number) {
    const item = entries.get(key);
    if (!item || item.expiresAt <= nowMs) return undefined;
    return item.value;
  }

  function has(key: string, nowMs: number) {
    const item = entries.get(key);
    return !!(item && item.expiresAt > nowMs);
  }

  function deleteEntry(key: string) {
    return entries.delete(key);
  }

  function size(nowMs: number) {
    let count = 0;
    for (const [key] of entries) {
      if (has(key, nowMs)) count++;
    }
    return count;
  }

  function clear() {
    entries.clear();
  }

  return {
    set,
    get,
    has,
    delete: deleteEntry,
    size,
    clear,
  };
}

interface TtlCache {
  set(key: string, value: unknown, nowMs: number, ttlMs?: number): void;
  get(key: string, nowMs: number): unknown;
  has(key: string, nowMs: number): boolean;
  delete(key: string): boolean;
  size(nowMs: number): number;
  clear(): void;
}
