export function createCalculator(): {
    result: () => number;
    add: (value: number) => this;
    subtract: (value: number) => this;
    multiply: (value: number) => this;
    divide: (value: number) => this;
    clear: () => this;
    memoryStore: () => this;
    memoryAdd: (value?: number) => this;
    memoryClear: () => this;
    memoryRecall: () => [number, this];
} {
    let current = 0;
    let memory = 0;

    return {
        result: () => current,

        add: (value: number) => {
            current += value;
            return this as this;
        },

        subtract: (value: number) => {
            current -= value;
            return this as this;
        },

        multiply: (value: number) => {
            current *= value;
            return this as this;
        },

        divide: (value: number) => {
            if (value === 0) return this;
            current /= value;
            return this as this;
        },

        clear: () => {
            current = 0;
            return this as this;
        },

        memoryStore: () => {
            const tempMemory = current;
            current = 0;
            memory = tempMemory;
            return this as this;
        },

        memoryAdd: (value?: number) => {
            memory += value ?? current;
            return this as this;
        },

        memoryClear: () => {
            memory = 0;
            return this as this;
        },

        memoryRecall: () => [memory, { ...this } as typeof this]
    };
}
