export function createEventEmitter() {
    const listeners: Map<string, Function[]> = new Map();

    function on(eventName: string, listener: (...args: any[]) => any) {
        if (listeners.has(eventName)) {
            listeners.get(eventName)?.push(listener);
        } else {
            listeners.set(eventName, [listener]);
        }
    }

    function once(eventName: string, listener: (...args: any[]) => any) {
        function wrapper(...args: any[]) {
            listener(...args);
            off(eventName, wrapper);
        }
        on(eventName, wrapper);
    }

    function emit(eventName: string, ...args: any[]): any[] {
        const listenerFns = listeners.get(eventName);
        if (!listenerFns) return [];
        return listenerFns.map(fn => fn(...args));
    }

    function off(eventName: string, listener: (...args: any[]) => any) {
        const list = listeners.get(eventName);
        if (list) {
            const index = list.indexOf(listener);
            if (index !== -1) {
                list.splice(index, 1);
                if (list.length === 0) {
                    listeners.delete(eventName);
                }
            }
        }
    }

    return { on, once, emit, off };
}
