export function createRateLimiter(nowMs: () => number) {
    const buckets = new Map<string, { quota: number; lastResetTimestampMs: number }>();

    return {
        async rateLimit(key: string): Promise<boolean> {
            const currentTimestampMs = nowMs();
            const bucketData = buckets.get(key) || { quota: 3, lastResetTimestampMs: -1 };
            if (bucketData.lastResetTimestampMs >= currentTimestampMs) {
                // Bucket is not yet reset
                return bucketData.quota > 0;
            }

            // Reset the bucket and start a new window
            buckets.set(key, { quota: 3, lastResetTimestampMs: currentTimestampMs });
            return true;
        },
        reset(key: string): void {
            const cleared = buckets.delete(key);
            if (cleared) {
                // Key was cleared, but other keys may still be active
                const now = nowMs();
                buckets.forEach((bucketData) => {
                    if (now - bucketData.lastResetTimestampMs >= 1000) {
                        bucketData.quota = 3;
                        bucketData.lastResetTimestampMs = now;
                    }
                });
            }
        },
    };
}
