export function createRateLimiter(): RateLimiter {
  const windows: Record<string, number[]> = {};

  function allow(key: string, nowMs: number): boolean {
    if (!windows[key] || nowMs - windows[key][0] >= 1000) {
      windows[key] = [nowMs];
      return true;
    }

    const remaining = Math.min(windows[key].length, 3);
    if (remaining === 0) {
      return false;
    }

    windows[key] = [...windows[key], nowMs];
    windows[key] = windows[key].slice(-3);

    return remaining > 0;
  }

  function remaining(key: string, nowMs: number): number {
    const windowStart = Math.max(0, nowMs - 1000);
    let count = 0;

    for (let i = 0; i < windows[key].length; i++) {
      if (windows[key][i] >= windowStart) {
        count++;
      } else {
        break;
      }
    }

    return Math.min(3, 3 - (count > 3 ? 1 : 0));
  }

  function reset(key: string): void {
    delete windows[key];
  }

  return {
    allow,
    remaining,
    reset
  };
}
