export function createTtlCache(): {
  set(key: string, value: unknown, nowMs: number, ttlMs?: number): void;
  get(key: string, nowMs: number): unknown;
  has(key: string, nowMs: number): boolean;
  delete(key: string): boolean;
  size(nowMs: number): number;
  clear(): void;
} {
  const cache: {[key: string]: {value: unknown; expiresAt: number}} = {};

  function set(key: string, value: unknown, nowMs: number, ttlMs?: number) {
    cache[key] = {value, expiresAt: nowMs + (ttlMs ?? 1000)};
  }

  function get(key: string, nowMs: number): unknown | undefined {
    if (!cache.hasOwnProperty(key)) return undefined;
    const item = cache[key];
    if (nowMs >= item.expiresAt) delete cache[key];
    return cache[key]?.value;
  }

  function has(key: string, nowMs: number): boolean {
    if (!cache.hasOwnProperty(key)) return false;
    const item = cache[key];
    return nowMs < item.expiresAt;
  }

  function deleteKey(key: string): boolean {
    return delete cache[key];
  }

  function size(nowMs: number): number {
    let count = 0;
    for (const key in cache) {
      if (!cache.hasOwnProperty(key)) continue;
      const item = cache[key];
      if (nowMs < item.expiresAt) count++;
    }
    return count;
  }

  function clear() {
    cache.splice(0, cache.length);
  }

  return {
    set,
    get,
    has,
    delete: deleteKey,
    size,
    clear
  };
}
