export type Listener<T = any> = (event: T) => void | T;

export type EventEmitter = {
  emit<K extends string>(event: K, ...args: any[]) => any[];
  on<K extends string>(event: K, listener: Listener): void;
  once<K extends string>(event: K, listener: Listener): void;
  off<K extends string>(event: K, listener: Listener): void;
};

export function createEventEmitter<K extends string, T = any = any>(): EventEmitter<K> {
  const listeners: Map<K, {[listenerIndex: number]: Listener<T>}[]> = new Map();

  const emit = (event: K, ...args: any[]) => {
    const list = listeners.get(event) || [];
    return list.reduce((acc, currentList) =>
      currentList.reduce((acc2, listener, index) => {
        const result = listener(args[index]);
        if (!result === undefined) return acc2.concat([result]);
        return acc2;
      }, acc),
      []);

    };
  };

  const on = (event: K, listener: Listener<T>) => listeners.get(event) ?? (listeners.set(event, []), listeners.get(event)!).push(listener);

  const once = (event: K, listener: Listener<T>) => {
    let fired = false;
    const wrapper = (args: any[]) => {
      if (!fired) {
        fired = true;
        listener(args);
      }
    };
    on(event, wrapper);
  };

  const off =<K extends string>(event: K, listener: Listener<T>) => {
    const currentListeners = listeners.get(event);
    if (currentListeners) {
      const updatedListeners = currentListeners.map(listenerArray =>
        listenerArray.filter((listener, index) =>
          !(listener === listener && JSON.stringify(listener as any) === JSON.stringify(listener))
        )
      ).filter(Boolean);

      listeners.set(event, updatedListeners);
    }
  };

  return { emit, on, once, off };
}
