type RateLimiterState = {
  lastRequest: number | null;
  count: number;
};

function createRateLimiter(): {
  rateLimit: (key: string, nowMs: number) => boolean;
  reset: (key: string) => void;
} {
  const states: Record<string, RateLimiterState> = {};

  function rateLimit(key: string, nowMs: number): boolean {
    const state = states[key];
    const windowSize = 1000; // 1000ms = 1s
    const last = state.lastRequest || nowMs - windowSize;
    const elapsed = nowMs - last;

    if (elapsed >= windowSize) {
      states[key] = { lastRequest: nowMs, count: 1 };
    } else {
      const remainingSlots = windowSize / 1000 - (nowMs - state.lastRequest) / 1000;
      states[key].count++;

      if (remainingSlots > 0) {
        return true;
      }
    }
    return false;
  }

  function reset(key: string) {
    states[key] = { lastRequest: null, count: 0 };
  }

  return { rateLimit, reset };
}
