export function createRateLimiter(): RateLimiter {
  const storage: Record<string, { count: number; windowStart: number }> = {};

  function allow(key: string, nowMs: number): boolean {
    const windowStart = Math.max(storage[key]?.windowStart ?? nowMs - windowMs, 0);
    const remainingMs = windowMs - (nowMs - windowStart);
    if (remainingMs < 0) {
      storage[key] = { count: 1, windowStart };
      return true;
    }

    const entry = storage[key];
    if (entry && entry.count < limit) {
      entry.count += 1;
      // Do not let remaining quota drop below 0
      return remainingMs >= limit * windowMs / (limit - entry.count) && entry.count < limit;
    }

    return false;
  }

  function remaining(key: string, nowMs: number): number {
    const windowStart = Math.max((storage[key]?.windowStart ?? nowMs - windowMs) + 1, 0);
    const elapsed = nowMs - windowStart;
    if (elapsed < 0 || elapsed >= windowMs) return limit;
    const used = Math.min(storage[key]?.count ?? 0, limit);
    return limit - used;
  }

  function reset(key: string): void {
    delete storage[key];
  }

  const limit = 3;
  const windowMs = 1000;

  return {
    allow,
    remaining,
    reset,
  };
}

type RateLimiter = ReturnType<typeof createRateLimiter>;
