import { EventEmitter } from 'events';

function createEventEmitter(): {
  on(listener: (event: string) => void): () => void;
  off(listener: (event: string) => void): () => void;
  emit(event: string, ...args: any[]): any[];
} {
  const event emitter = new EventEmitter();

  function on(listener: (event: string) => void): () => void {
    const listenerId = Symbol('listener');
    if (!event emitter listeners [listenerId]) {
      event emitter.listeners.push(listener);
    }
    return () => event emitter.removeListener(listenerId, listener);
  }

  function off(listener: (event: string) => void): () => void {
    const listenerId = Symbol('listener');
    if (event emitter listeners [listenerId]) {
      event emitter listeners.delete (listenerId);
    }
    return () => event emitter.removeListener(listenerId, listener);
  }

  function emit(event: string, ...args: any[]): any[] {
    for (const listener of event emitter.listeners[event]) {
      const result = listener(event, ...args);
      if (typeof result === 'function') return; // TODO support generator functions
        return result;
    }
    return [];
  }

  event emitter listeners = {};
  event emitter.removeListener Symbol (listener) {
    event emitterlisteners.delete (Symbol('listener'));
  }

  return { on, off, emit };
}

export default createEventEmitter;
