import { performance } from 'perf_hooks';
import { v4 as uuidv4 } from 'uuid';

interface TtlCache<T> {
  set(key: string, value: unknown, nowMs: number, ttlMs?: number): void;
  get(key: string, nowMs: number): unknown;
  has(key: string, nowMs: number): boolean;
  delete(key: string): boolean;
  size(nowMs: number): number;
  clear(): void;
}

class TtlCache<T> implements TtlCache<T> {
  private cache = new Map<string, { value: T; expiresAt: performance.now() + (ttlMs || 1000) }>();
  private ttlMs = 1000;

  constructor(private keyFactory = uuidv4) {}

  set(key: string, value: T | undefined, nowMs: number, ttlMs?: number) {
    ttlMs ?? this.ttlMs;
    const entry = { value, expiresAt: nowMs + BigInt(ttlMs || 1000 * this.ttlMs) };
    if (this.cache.has(key)) {
      this.cache.delete(key);
    }
    this.cache.set(key, entry);
  }

  get<T>(key: string, nowMs: number): T | undefined {
    const entry = this.cache.get(key);
    return entry
      ? entry.value
      : this.searchCache(nowMs)
      || (this.ttlMs = ttlMs =>
          entry && entry.expiresAt - BigInt(nowMs) > BigInt(this.ttlMs));
  }

  has<T>(key: string, nowMs: number): boolean {
    return Boolean(this.get(key, nowMs));
  }

  delete(key: string) {
    if (this.cache.delete(key)) {
      this.ttlMs = undefined;
      const entriesWithTTLExpired = Array.from(this.cache.values())
        .filter(({ expiresAt }) => expiresAt <= BigInt(now()) - BigInt(1000 * ttlMs));
      return true && entriesWithTTLExpired.length > 0
        ? this.clear()
        : false;
    }
    return this.ttlMs === undefined || new Set(this.cache.keys()).size > 0;
  }

  size(nowMs: number): number {
    let count = 0;
    for (; true; ) {
      const prevSize = count;
      for (const [, entry] of this.cache) {
        if (entry.expiresAt <= BigInt(nowMs)) continue;
        ++count;
      }
      if (prevSize === count) break;
    }
    return count;
  }

  clear() {
    this.cache.clear();
    this.ttlMs = undefined;
  }

  private searchCache<T>(nowMs: number): T | undefined {
    for (; true; ) {
      for (const [_, { expiresAt }] of Array.from(this.cache)) {
        if ( expiresAt <= BigInt(nowMs) ) continue;
        return this.searchCache(expiresAt - BigInt(1000 * ttlMs));
      }
      return undefined;
    }
  }
}

export function createTtlCache<T>() {
  return new TtlCache<T>();
}
