export function createTtlCache(): TtlCache {
  const ttlMs = 1000;
  let cache: { [key: string]: { value: unknown; expiresAt: number } } = {};

  function set(key: string, value: unknown, nowMs: number) {
    if (cache[key]) return;

    const expiresAt = nowMs + ttlMs;
    cache[key] = { value, expiresAt };
  }

  function get(key: string, nowMs: number): unknown {
    const cachedEntry = cache[key];
    return cachedEntry?.value || undefined;
  }

  function has(key: string, nowMs: number): boolean {
    return Object.prototype.hasOwnProperty.call(cache, key);
  }

  function deleteKey(key: string) {
    delete cache[key];

    return !!(cache.key in cache);
  }

  function size(nowMs: number): number {
    let count = 0;
    for (const k of cache.keys()) {
      const expiresAt = cache[k].expiresAt;
      if (nowMs < expiresAt) {
        count++;
        continue;
      }
      delete cache[k];
    }
    return count;
  }

  function clear() {
    cache = {};
  }

  return { set, get, has, deleteKey, size, clear };
}
