interface EventMap {
  [eventName: string]: Array<{
    listener: Function;
    isOnce: boolean;
    ref: number;
    equals: (other: any) => boolean;
  }>;
}

type Listener = (...args: any[]) => any;
type EventEmitter = {
  on: (eventName: string, listener: Listener) => EventEmitter;
  once: (eventName: string, listener: Listener) => EventEmitter;
  off: (eventName: string, listener: Listener) => EventEmitter;
  emit: (eventName: string, ...args: any[]) => Promise<any[]>;
};

function createEventEmitter(): EventEmitter {
  const listeners = Object.create(null) as EventMap;
  let listenerCounter = 0;

  function normalizeEventName(eventName: string): void {
    if (!listeners[eventName]) {
      listeners[eventName] = [];
    }
  }

  function createListenerWrapper(listener: Listener, isOnce: boolean): EventMap[string][0] {
    const ref = listenerCounter++;
    return {
      listener,
      isOnce,
      ref,
      equals: (other: any) => {
        if (!other || typeof other !== 'object') return false;
        return other.listener && other.listener === listener && other.isOnce === isOnce;
      }
    };
  }

  function compareListener(event: typeof listeners[string][0], candidate: EventMap[string][0]): boolean {
    if (!candidate || typeof candidate !== 'object') return false;
    return candidate.listener && event.listener === candidate.listener && event.isOnce === candidate.isOnce;
  }

  function removeListener(eventListeners: EventMap[string], candidate: EventMap[string][0], index: number): boolean {
    if (compareListener(eventListeners[index], candidate)) {
      eventListeners.splice(index, 1);
      return true;
    }
    return false;
  }

  const emitter: EventEmitter = {
    on(eventName: string, listener: Listener): EventEmitter {
      normalizeEventName(eventName);
      listeners[eventName].push(createListenerWrapper(listener, false));
      return emitter;
    },

    once(eventName: string, listener: Listener): EventEmitter {
      normalizeEventName(eventName);
      listeners[eventName].push(createListenerWrapper(listener, true));
      return emitter;
    },

    off(eventName: string, listener: Listener): EventEmitter {
      if (!listeners[eventName]) {
        return emitter;
      }

      const eventListeners = listeners[eventName];
      for (let i = 0; i < eventListeners.length; i++) {
        if (compareListener(eventListeners[i], { listener, isOnce: false })) {
          eventListeners.splice(i, 1);
          break;
        }
      }

      return emitter;
    },

    async emit(eventName: string, ...args: any[]): Promise<any[]> {
      normalizeEventName(eventName);
      const eventListeners = listeners[eventName];
      const results: any[] = [];
      const toRemove: typeof eventListeners = [];

      for (const listenerWrapper of eventListeners) {
        const currentIsOnce = listenerWrapper.isOnce;
        const currentListener = listenerWrapper.listener;

        results.push(await Promise.resolve(currentListener(...args)));

        if (currentIsOnce) {
          toRemove.push(listenerWrapper);
        }
      }

      for (const wrapper of toRemove) {
        const index = eventListeners.findIndex(w => w === wrapper);
        if (index !== -1) {
          eventListeners.splice(index, 1);
        }
      }

      return results;
    }
  };

  return emitter;
}

export { createEventEmitter };
