type Listener = (payload: unknown) => unknown

interface EventEmitter {
  on(event: string, listener: Listener): number
  once(event: string, listener: Listener): number
  off(event: string, listener: Listener): boolean
  emit(event: string, payload: unknown): unknown[]
  listenerCount(event: string): number
}

export function createEventEmitter(): EventEmitter {
  type ListenerEntry = {
    fn: Listener
    once: boolean
  }

  const events: Map<string, ListenerEntry[]> = new Map()

  const getEvent = (eventName: string): ListenerEntry[] => {
    if (!events.has(eventName)) {
      events.set(eventName, [])
    }
    return events.get(eventName)!
  }

  return {
    on(eventName: string, listener: Listener): number {
      const event = getEvent(eventName)
      event.push({ fn: listener, once: false })
      return event.length
    },

    once(eventName: string, listener: Listener): number {
      const event = getEvent(eventName)
      event.push({ fn: listener, once: true })
      return event.length
    },

    off(eventName: string, listener: Listener): boolean {
      const event = events.get(eventName)
      if (!event) return false

      const index = event.findIndex(entry => entry.fn === listener)
      if (index !== -1) {
        event.splice(index, 1)
        if (event.length === 0) {
          events.delete(eventName)
        }
        return true
      }
      return false
    },

    emit(eventName: string, payload: unknown): unknown[] {
      const event = events.get(eventName)
      if (!event) return []

      const results: unknown[] = []

      for (const entry of event) {
        const result = entry.fn(payload)
        results.push(result)
      }

      for (let i = event.length - 1; i >= 0; i--) {
        if (event[i].once) {
          event.splice(i, 1)
        }
      }

      if (event.length === 0) {
        events.delete(eventName)
      }

      return results
    },

    listenerCount(eventName: string): number {
      const event = events.get(eventName)
      return event?.length || 0
    }
  }
}
