export function createTtlCache() {
  type CacheEntry = {
    key: string
    value: unknown
    expiresAt: number
  }

  const entries: CacheEntry[] = []

  return {
    set(key: string, value: unknown, nowMs: number, ttlMs = 1000) {
      const expiresAt = nowMs + ttlMs
      const existingIndex = entries.findIndex(entry => entry.key === key)

      if (existingIndex >= 0) {
        entries[existingIndex] = { key, value, expiresAt }
      } else {
        entries.push({ key, value, expiresAt })
      }
    },

    get(key: string, nowMs: number) {
      const entry = entries.find(entry => entry.key === key)
      return entry?.expiresAt > nowMs ? entry?.value : undefined
    },

    has(key: string, nowMs: number) {
      return entries.some(entry => entry.key === key && entry.expiresAt > nowMs)
    },

    delete(key: string) {
      const initialLength = entries.length
      for (let i = entries.length - 1; i >= 0; i--) {
        if (entries[i].key === key) {
          entries.splice(i, 1)
        }
      }
      return entries.length < initialLength
    },

    size(nowMs: number) {
      let count = 0
      for (const entry of entries) {
        if (entry.expiresAt > nowMs) {
          count++
        }
      }
      return count
    },

    clear() {
      entries.length = 0
    }
  }
}
