export function createEventEmitter(): EventEmitter {
    const listeners: Map<string, Listener[]> = new Map();
    const onceListeners: Map<string, { listener: Listener, used: boolean }[]> = new Map();

    return {
        on(event: string, listener: Listener): number {
            listeners.set(event, [...(listeners.get(event) || []), listener]);
            return listeners.get(event) ? listeners.get(event).length : 0;
        },

        once(event: string, listener: Listener): number {
            onceListeners.set(event, [...(onceListeners.get(event) || []), { listener, used: false }]);
            return onceListeners.get(event) ? onceListeners.get(event).length : 0;
        },

        off(event: string, listener: Listener): boolean {
            const eventListeners = listeners.get(event) || [];
            const index = eventListeners.indexOf(listener);
            if (index === -1) return false;
            listeners.set(event, [...eventListeners.slice(0, index), ...eventListeners.slice(index + 1)]);
            return true;
        },

        emit(event: string, payload: unknown): unknown[] {
            const result: unknown[] = [];
            const currentListeners = listeners.get(event) || [];
            const currentOnceListeners = onceListeners.get(event) || [];

            currentListeners.forEach(listener => result.push(listener(payload)));

            for (const onceListener of [...currentOnceListeners]) {
                if (!onceListener.used) {
                    onceListener.used = true;
                    result.push(onceListener.listener(payload));
                }
            }

            const updatedOnceListeners = currentOnceListeners
                .map(onceListener => ({ listener: onceListener.listener, used: onceListener.listener === listener ? onceListener.used : false }))
                .filter(onceListener => !onceListener.used);

            onceListeners.set(event, updatedOnceListeners);

            return result;
        },

        listenerCount(event: string): number {
            return listeners.get(event)?.length || 0;
        },
    };
}

type Listener = (payload: unknown) => unknown;

interface EventEmitter {
    on(event: string, listener: Listener): number;
    once(event: string, listener: Listener): number;
    off(event: string, listener: Listener): boolean;
    emit(event: string, payload: unknown): unknown[];
    listenerCount(event: string): number;
}
