/**
 * Creates a calculator instance with memory functionality.
 * The calculator starts at value 0. Memory starts at 0.
 *
 * Features:
 * - Basic arithmetic operations: add, subtract, multiply, divide
 * - Memory functions: store, add to memory, clear memory
 * - Memory recall without affecting current value
 * - Each operation returns the calculator instance for chaining
 *
 * All methods return the calculator instance for method chaining.
 */
export function createCalculator() {
  // Private state tracking
  let _result = 0; // Current calculator value
  let _memory = 0; // Memory storage

  // Return self for chaining
  const self = {
    /**
     * Add a value to the calculator
     */
    add(value: number) {
      _result += value;
      return self;
    },

    /**
     * Subtract a value from the calculator
     */
    subtract(value: number) {
      _result -= value;
      return self;
    },

    /**
     * Multiply the calculator by a value
     */
    multiply(value: number) {
      _result *= value;
      return self;
    },

    /**
     * Divide the calculator by a value
     */
    divide(value: number) {
      _result /= value;
      return self;
    },

    /**
     * Clear the calculator to zero
     */
    clear() {
      _result = 0;
      return self;
    },

    /**
     * Get the current calculator value
     */
    result() {
      return _result;
    },

    /**
     * Store the current value into memory
     */
    memoryStore() {
      _memory = _result;
      return self;
    },

    /**
     * Add the current value to memory (memory remains unchanged)
     */
    memoryAdd() {
      _memory += _result;
      return self;
    },

    /**
     * Clear memory
     */
    memoryClear() {
      _memory = 0;
      return self;
    },

    /**
     * Recall memory value without affecting current result value
     */
    memoryRecall() {
      return _memory;
    }
  };

  return self;
}
