/**
 * Creates a rate limiter with a fixed policy of 3 requests per 1000ms window.
 */
export function createRateLimiter(): RateLimiter {
  // Fixed policy: limit = 3, windowMs = 1000
  const windows = new Map<string, { count: number; startMs: number }>();

  return {
    /**
     * Allow a request for a key at the given time.
     * Returns true if allowed, false if rejected.
     */
    allow(key: string, nowMs: number): boolean {
      const ws = windows.get(key);
      const limit = 3;
      const windowMs = 1000;

      if (!ws || nowMs - ws.startMs >= windowMs) {
        // Start a fresh window for this key
        windows.set(key, { count: 1, startMs: nowMs });
        return true;
      }

      if (ws.count < limit) {
        ws.count++;
        return true;
      }

      // Rejected: at limit for this key
      return false;
    },

    /**
     * Remaining allowed requests for a key at the given time.
     * Returns >=0 remaining requests, or <=0 if rejected.
     */
    remaining(key: string, nowMs: number): number {
      const ws = windows.get(key);
      const limit = 3;
      const windowMs = 1000;

      if (!ws || nowMs - ws.startMs >= windowMs) {
        // Not in a window: treat as fresh start
        return limit - 1;
      }

      const remaining = limit - ws.count;
      return remaining >= 0 ? remaining : -1;
    },

    /**
     * Reset the window for a key, removing its state.
     */
    reset(key: string): void {
      windows.delete(key);
    },
  };
}
