/**
 * Creates a TTL (Time-To-Live) cache with expiration logic.
 * The cache entries will be stored with expiration times that are calculated based on the current timestamp.
 */
export function createTtlCache() {
  const internalCache = new Map<string, CacheEntry>();

  /**
   * Represents an entry in the cache.
   */
  interface CacheEntry {
    /** The value stored in the cache. */
    value: unknown;
    /** The timestamp when the entry should expire. Deterministic and strict expiration. */
    expiresAt: number;
  }

  /**
   * Stores or overwrites a value in the cache with TTL.
   * 
   * @param key - The cache key.
   * @param value - The value to store.
   * @param nowMs - The current timestamp in milliseconds. Used to calculate expiration.
   * @param ttlMs - Optional time-to-live in milliseconds for the entry.
   */
  function set(key: string, value: unknown, nowMs: number, ttlMs?: number): void {
    // Calculate expiration time deterministically with the provided timestamp
    const expiresAt = nowMs + (ttlMs ?? 1000); // Default to 1000ms if not provided
    internalCache.set(key, { value, expiresAt });
  }

  /**
   * Retrieves a value from the cache if it hasn't expired.
   * 
   * @param key - The cache key.
   * @param nowMs - The current timestamp in milliseconds.
   * @returns The value if valid, `undefined` if expired or not found.
   */
  function get(key: string, nowMs: number): unknown {
    const entry = internalCache.get(key);
    if (!entry || nowMs >= entry.expiresAt) {
      // Entry missing or expired, remove it
      internalCache.delete(key);
      return undefined;
    }
    return entry.value;
  }

  /**
   * Checks if a key exists and is valid (not expired).
   * 
   * @param key - The cache key.
   * @param nowMs - The current timestamp in milliseconds.
   * @returns `true` if the key exists and is valid.
   */
  function has(key: string, nowMs: number): boolean {
    const entry = internalCache.get(key);
    // If missing or expired, remove it
    if (!entry || nowMs >= entry.expiresAt) {
      internalCache.delete(key);
      return false;
    }
    return true;
  }

  /**
   * Removes all entries from the cache.
   */
  function clear(): void {
    internalCache.clear();
  }

  /**
   * Returns the number of live entries in the cache.
   * 
   * @param nowMs - The current timestamp in milliseconds.
   * @returns The count of live (non-expired) entries.
   */
  function size(nowMs: number): number {
    let count = 0;
    for (const [key, entry] of internalCache.entries()) {
      if (nowMs < entry.expiresAt) {
        count++;
      } else {
        // Clean up expired entries during iteration
        internalCache.delete(key);
      }
    }
    return count;
  }

  return {
    set,
    get,
    has,
    delete: internalCache.delete.bind(internalCache),
    size,
    clear,
  };
}

