/**
 * Creates a TTL (Time To Live) cache implementation with configurable expiration times for cache entries.
 * This cache supports setting, getting, checking existence, deletion, and clearing of cache entries with TTL functionality.
 *
 * @returns {TtlCache} A configured TTL cache instance.
 */
export function createTtlCache(): TtlCache {
  // Internal cache store with timestamps and expiration data
  const store = new Map<string, { value: unknown; expiresAt: number }>();

  /**
   * Sets a value in the cache with a TTL (Time To Live) expiration.
   *
   * @param key - The key to store the value under.
   * @param value - The value to store.
   * @param nowMs - The current timestamp in milliseconds.
   * @param ttlMs - The time-to-live in milliseconds (0 for immediate expiration).
   */
  function set(key: string, value: unknown, nowMs: number, ttlMs: number = 1000): void {
    const expiresAt = ttlMs === 0 ? nowMs - 1 : nowMs + ttlMs;
    store.set(key, { value, expiresAt });
  }

  /**
   * Gets a value from the cache if it hasn't expired.
   *
   * @param key - The key to retrieve the value for.
   * @param nowMs - The current timestamp in milliseconds.
   * @returns The value if it exists and hasn't expired, otherwise `undefined`.
   */
  function get(key: string, nowMs: number): unknown {
    const entry = store.get(key);
    if (!entry || nowMs >= entry.expiresAt) {
      store.delete(key);
      return undefined;
    }
    return entry.value;
  }

  /**
   * Checks if a key exists in the cache and hasn't expired.
   *
   * @param key - The key to check.
   * @param nowMs - The current timestamp in milliseconds.
   * @returns `true` if the key exists and hasn't expired, otherwise `false`.
   */
  function has(key: string, nowMs: number): boolean {
    const entry = store.get(key);
    if (!entry || nowMs >= entry.expiresAt) {
      store.delete(key);
      return false;
    }
    return true;
  }

  /**
   * Deletes a key from the cache.
   *
   * @param key - The key to delete.
   * @returns `true` if the key was deleted, otherwise `false`.
   */
  function delete(key: string): boolean {
    return store.delete(key);
  }

  /**
   * Clears all expired entries from the cache.
   *
   * @param nowMs - The current timestamp in milliseconds.
   * @returns The number of non-expired entries removed.
   */
  function size(nowMs: number): number {
    let count = 0;
    for (const [key, { expiresAt }] of store) {
      if (nowMs >= expiresAt) {
        store.delete(key);
      } else {
        count++;
      }
    }
    return count;
  }

  /**
   * Clears all entries from the cache.
   */
  function clear(): void {
    store.clear();
