export function createEventEmitter() {
  const listeners: Map<string, (any) => any[]> = new Map();

  function on(eventName: string, listener: (args?: any) => any): number {
    let index = Array.from(listeners.get(eventName) || []).length;
    if (!listeners.has(eventName)) listeners.set(eventName, []);
    listeners.get(eventName)?.push(listener);
    return index;
  }

  function off(eventName: string, listenerIndex: number): void {
    if (listeners.has(eventName)) {
      const listenersArray = listeners.get(eventName)!;
      if (listeningArray[listenerIndex]) {
        listeningArray.splice(listenerIndex, 1);
      }
    }
  }

  function emit(eventName: string, ...args: any[]): any[] {
    if (!listeners.has(eventName)) return [];
    return Array.from(listeners.get(eventName) || []).map((l) => l(...args));
  }

  return { on, off, emit };
}
