export function createEventEmitter(): EventEmitter {
  const listeners: Record<string, Listener[]> = {};

  return {
    on(event: string, listener: Listener): number {
      if (!listeners[event]) {
        listeners[event] = [];
      }
      listeners[event].push(listener);
      return listeners[event].length;
    },

    once(event: string, listener: Listener): number {
      const wrappedListener: Listener = (...args) => {
        this.off(event, wrappedListener);
        return listener(...args);
      };

      this.on(event, wrappedListener);
      return listeners[event].length - 1; // Subtract one because we just added the once listener
    },

    off(event: string, listener: Listener): boolean {
      if (!listeners[event]) return false;

      const filteredListeners = listeners[event].filter(l => l !== listener);
      if (filteredListeners.length === listeners[event].length) return false;
      listeners[event] = filteredListeners;

      return true;
    },

    emit(event: string, payload: unknown): unknown[] {
      if (!listeners[event]) return [];

      const results: unknown[] = [];
      for (const listener of listeners[event]) {
        results.push(listener(payload));
      }
      return results;
    },

    listenerCount(event: string): number {
      return listeners[event]?.length || 0;
    }
  };
}
