export function createRateLimiter(): RateLimiter {
  const cache: Map<string, { keyData: KeyData; windowStartMs: number }> = new Map();

  class KeyData {
    attemptsMade: number = 0;
  }

  return {
    allow(key: string, nowMs: number): boolean {
      let keyDataEntry = cache.get(key);
      const windowStartMs = ((nowMs / 1000) | 0) * 1000;

      if (!keyDataEntry || (windowStartMs - keyDataEntry.windowStartMs >= 1000)) {
        // Reset the key after a new window has started
        cache.set(key, { keyData: new KeyData(), windowStartMs });
      } else {
        keyDataEntry.keyData.attemptsMade++;
      }

      if (keyDataEntry?.keyData.attemptsMade >= 3) {
        return false;
      }

      const remainingAttempts = 3 - keyDataEntry?.keyData.attemptsMade;

      return true;
    },

    remaining(key: string, nowMs: number): number {
      let keyDataEntry = cache.get(key);
      const windowStartMs = ((nowMs / 1000) | 0) * 1000;

      if (!keyDataEntry || (windowStartMs - keyDataEntry.windowStartMs >= 1000)) {
        // Reset the key after a new window has started
        cache.set(key, { keyData: new KeyData(), windowStartMs });
      }

      return 3 - (keyDataEntry?.keyData.attemptsMade ?? 0);
    },

    reset(key: string): void {
      const entry = cache.get(key);
      if (entry) {
        entry.keyData.attemptsMade = 0;
        entry.windowStartMs = ((now() / 1000) | 0) * 1000;
      }
    }
  };
