export function createTtlCache(): TtlCache {
  const cache: Map<string, { value: unknown; expiresAt: number }> = new Map();

  function set(key: string, value: unknown, nowMs: number, ttlMs?: number): void {
    if (value === undefined) {
      delete cache.get(key);
    } else {
      cache.set(key, { value, expiresAt: nowMs + (ttlMs ?? 1000) });
    }
  }

  function get(key: string, nowMs: number): unknown {
    const entry = cache.get(key);
    if (!entry || nowMs >= entry.expiresAt) return undefined;
    return entry.value;
  }

  function has(key: string, nowMs: number): boolean {
    const entry = cache.get(key);
    return entry && nowMs < entry.expiresAt;
  }

  function deleteKey(key: string): boolean {
    return cache.delete(key);
  }

  function size(nowMs: number): number {
    let count = 0;
    for (const key of cache.keys()) {
      if (!cache.get(key)?.expiresAt || nowMs < cache.get(key).expiresAt) count++;
    }
    return count;
  }

  function clear(): void {
    cache.clear();
  }

  return {
    set,
    get,
    has,
    delete: deleteKey,
    size,
    clear
  };
}
