import type { EventName, Emitter } from "./types";

export function createEventEmitter<T extends EventName = any>(prefix?: string): Emitter<T, unknown> {
  const events = new Map<string, Array<(values: unknown[]) => unknown>>();
  const prefixKey = prefix ? (name: string) => `${prefix}.${name}` : (name: string) => name;

  return {
    emit: (<E extends EventName>(name: E, ...values: Parameters<Event<T extends E>[E]>) => unknown) => {
      const namePrefixed = prefixKey(name);
      if (!events.has(namePrefixed)) return [];

      for (const listener of events.get(namePrefixed)!) {
        const result = listener([...values]);
        if (result !== undefined) return [result];
      }
      return [];
    },
    on: (<E extends EventName>(
      name: E,
      listener: (values: Parameters<Event<T extends E>[E]>) => ReturnType<Event<T extends E>[E]>
    ) => void) => {
      const namePrefixed = prefixKey(name);
      if (!events.has(namePrefixed)) events.set(namePrefixed, []);
      events.get(namePrefixed)!.push(listener);
    },
    one: <E extends EventName>(name: E, listener: (values: Parameters<Event<T extends E>[E]>) => unknown) => void => {
      const namePrefixed = prefixKey(name);
      const listeners = events.get(namePrefixed)!;
      if (!listeners) events.set(namePrefixed, [listener]);
      else listeners.unshift(listener);
    },
    off: (<E extends EventName>(name: E, listener: (values: Parameters<Event<T extends E>[E]>) => unknown) => void) => {
      const namePrefixed = prefixKey(name);
      if (!events.has(namePrefixed)) return;
      const listeners = events.get(namePrefixed)!;
      const index = listeners.findIndex((l) => l === listener);
      if (index === -1) return;
      listeners.splice(index, 1);
    }
  };
}
