type Listener = (payload: unknown) => void;

interface EventEmitter {
  on(event: string, listener: Listener): number;
  once(event: string, listener: Listener): number;
  off(event: string, listener: Listener): boolean;
  emit(event: string, payload: unknown): void[];
  listenerCount(event: string): number;
  listeners(event: string): Listener[];
}

const emitters: Record<string, { listeners: Listener[], onceListeners: { payload: unknown; listener: Listener }[] }> = {};

function createEventEmitter(): EventEmitter {
  return {
    on(event, listener) {
      const eventEmitter = emitters[event] || { listeners: [], onceListeners: [] };
      const oldListeners = eventEmitter.listeners.concat(listener);
      emitters[event] = { listeners: oldListeners, onceListeners: eventEmitter.onceListeners };

      return Object.values(emitters)[0][0].listeners.length || 0;
    },
    once(event, listener) {
      const eventEmitter = emitters[event] || { listeners: [], onceListeners: [] };
      const oldOnceListeners = { payload: undefined, listener } as { listener: Listener };

      emitters[event] = {
        listeners: eventEmitter.listeners,
        onceListeners: [...eventEmitter.onceListeners, oldOnceListeners]
      };

      return Object.values(emitters)[0][0].listeners.length || 0;
    },
    off(event, listener) {
      const targets = emitters[event] || [];
      const updatedListeners = targets.listeners.filter(it => !it.equals(listener));

      const updatedOnceListeners = targets.onceListeners.filter(it => it.listener != listener);

      if (updatedListeners.length > 0) emitters[event] = { listeners: updatedListeners, onceListeners: updatedOnceListeners };

      return updatedOnceListeners.length === 0;
    },
    emit(event, payload) {
      const eventEmitter = emitters[event] || { listeners: [], onceListeners: [] };

      const result: unknown[] = [];
      eventEmitter.listeners.forEach(listener => listener(payload));
      emitters[event] = { listeners: eventEmitter.listeners, onceListeners: eventEmitter.onceListeners };

      return result;

    },
    listenerCount(event) {
      return emitters[event]?.listeners.length || 0;
    },
    listeners(event) {
      return emitters[event]?.listeners;
    }
  };
}
